package com.innovatus.studentrecords.view; import com.innovatus.studentrecords.controller.OTPController; import com.innovatus.studentrecords.utils.DialogUtil; import javax.swing.*; import java.awt.*; public class ResetPasswordFrame extends BaseFrame {public ResetPasswordFrame(String e,OTPController c){super("Reset Password");JPasswordField p=new JPasswordField();JButton b=button("Reset");setLayout(new GridLayout(3,1));add(new JLabel("New password:"));add(p);add(b);b.addActionListener(x->{try{c.reset(e,new String(p.getPassword()));DialogUtil.info(this,"Password updated.");dispose();new LoginFrame().setVisible(true);}catch(Exception z){DialogUtil.error(this,z.getMessage());}});}}
